import { createHash } from "node:crypto";
import { z } from "zod";
import {
  type ProductScope,
  type ResearchDataset,
  type ResearchRecord,
  type Source,
  type LlmClient,
} from "@reqflow/core";
import {
  BMW_FEEDBACK_HEADERS,
  assessedSelection,
  researchTableRows,
  type ResearchTableRow,
} from "./tabular";
import { ASSESSMENT_FIELD } from "./assessment";
import {
  assertJsonByteBudget,
  jsonByteSize,
  PERSISTED_JSON_MAX_BYTES,
} from "./data-budget";

export { BMW_FEEDBACK_HEADERS };

// --- Summary & Assessment schemas for newly integrated quality source-assessments ---

export const SummaryExcerpt = z
  .object({
    start: z.number().int().nonnegative(),
    end: z.number().int().positive(),
  })
  .strict();
export type SummaryExcerpt = z.infer<typeof SummaryExcerpt>;

export const AssessmentSummaryItem = z
  .object({
    text: z.string().trim().min(1).max(3000),
    excerpts: z.array(SummaryExcerpt).default([]),
    tableRows: z.array(z.number().int().nonnegative()).default([]),
  })
  .passthrough();
export type AssessmentSummaryItem = z.infer<typeof AssessmentSummaryItem>;

export const SourceAssessmentWithSummaries = z
  .object({
    version: z.literal(1).default(1),
    agentId: z.string(),
    contentHash: z.string(),
    verdict: z.enum(["relevant", "irrelevant", "uncertain", "unreviewed"]),
    reasons: z.array(z.string().max(600)).default([]),
    uncertainties: z.array(z.string().max(600)).default([]),
    excerpts: z.array(SummaryExcerpt).default([]),
    tableRows: z.array(z.number().int().nonnegative()).default([]),
    model: z.string().default(""),
    summaries: z.array(AssessmentSummaryItem).default([]),
  })
  .passthrough();
export type SourceAssessmentWithSummaries = z.infer<
  typeof SourceAssessmentWithSummaries
>;

export type SummaryEvidence = {
  sourceId: string;
  collectedRecordId: string;
  locator?: string;
  excerpts: { start: number; end: number; text: string }[];
  tableEvidence?: {
    headers: string[];
    rows: unknown[][];
    rowIndices: number[];
  };
};

// --- Utility schemas and functions preserved for external tests and backwards compatibility ---

export const SummarizedFeedbackItem = z
  .object({
    brand: z.string().trim().min(1).default("[BMW]"),
    salesDescription: z.string().trim().min(1).default("[BMW 1 Series]"),
    country: z.string().trim().min(1).default("EU"),
    derivate: z.string().trim().min(1).default("F70"),
    engineType: z.enum(["ICE", "BEV", "PHEV", "unknown"]).default("ICE"),
    feedbackType: z
      .enum(["Likes", "Wants", "Defect", "Difficult to Use"])
      .default("Likes"),
    summary: z.string().trim().min(1),
    vfcLevel2Name: z.string().trim().min(1),
    vfcLevel3Name: z.string().trim().min(1),
  })
  .strict();

export type SummarizedFeedbackItem = z.infer<typeof SummarizedFeedbackItem>;

export const SourceSummariesResult = z
  .object({
    items: z.array(SummarizedFeedbackItem).min(1).max(5),
  })
  .strict();

export type SourceSummariesResult = z.infer<typeof SourceSummariesResult>;

export function defaultDerivate(model: string): string {
  if (/1\s*series|1er|f70/i.test(model)) return "F70";
  if (/5\s*series|5er|g60/i.test(model)) return "G60";
  if (/7\s*series|7er|g70/i.test(model)) return "G70";
  return "F70";
}

export function defaultSalesDescription(model: string): string {
  if (/1\s*series|1er|f70/i.test(model)) return "[BMW 1 Series]";
  if (/5\s*series|5er|g60/i.test(model)) return "[BMW 5 Series]";
  if (/7\s*series|7er|g70/i.test(model)) return "[BMW 7 Series]";
  return `[BMW ${model || "1 Series"}]`;
}

export const SUMMARIZER_SYSTEM = [
  "You are the BMW Research Summarizer and Feedback Analyst for product decision making.",
  "Your task is to analyze external research content (road tests, owner reviews, equipment lists, competitor benchmarks, forum discussions) and convert it into structured BMW-compatible feedback entries.",
].join("\n");

/** Legacy rule-based offline fallback preserved for external utility usage. */
export function offlineSummarizeRecord(
  record: ResearchRecord,
  source: Source | undefined,
  scope: ProductScope,
  overrideText?: string,
): SummarizedFeedbackItem {
  let text = overrideText;
  if (text === undefined) {
    const selection = assessedSelection(record);
    if (selection.excerpts.length > 0) {
      text = selection.excerpts
        .map(({ start, end }) => record.text.slice(start, end))
        .join("\n\n");
    } else {
      text = record.text;
    }
  }
  const cleanText = text.replace(/[\r\n]+/g, " ").trim();
  const lower = cleanText.toLowerCase();
  const vehicle = scope.vehicleLine || scope.vehicleCode || "1 Series";
  const derivate = defaultDerivate(vehicle);
  const salesDesc = defaultSalesDescription(vehicle);
  const country =
    typeof record.fields?.Country === "string"
      ? record.fields.Country
      : (record.marketAttribution?.value ?? scope.market ?? "EU");

  let feedbackType: SummarizedFeedbackItem["feedbackType"] = "Likes";
  if (
    /\b(defect|broken|fault|error|malfunction|damage|squeak|rattle)\b/i.test(
      lower,
    )
  ) {
    feedbackType = "Defect";
  } else if (
    /\b(difficult|awkward|distract|hard|complicated|annoy|confusing|frustrat|nightmare)\b/i.test(
      lower,
    )
  ) {
    feedbackType = "Difficult to Use";
  } else if (
    /\b(wish|want|need|missing|lack|should have|wants|request)\b/i.test(lower)
  ) {
    feedbackType = "Wants";
  }

  let vfcLevel2 = "General enquiry: customer feedback";
  let vfcLevel3 = "Like: function";

  if (
    /\b(touchscreen|touch|display|screen|idrive|software|navi|app|os9|os8|infotainment|bluetooth)\b/i.test(
      lower,
    )
  ) {
    vfcLevel2 = "ConnectedDrive and Infotainment, overall technology";
    vfcLevel3 =
      feedbackType === "Difficult to Use"
        ? "Not user-friendly"
        : feedbackType === "Defect"
          ? "Malfunction"
          : feedbackType === "Wants"
            ? "Customer request: usability"
            : "Like: function";
  } else if (/\b(seat|seating|chair|lumbar|sitz)\b/i.test(lower)) {
    vfcLevel2 = "Seats";
    vfcLevel3 =
      feedbackType === "Difficult to Use"
        ? "Not user-friendly"
        : feedbackType === "Likes"
          ? "Likes comfort"
          : "Customer request: function";
  } else if (
    /\b(steer|suspension|corner|ride|chassis|fahrwerk|handling|nimble|stability)\b/i.test(
      lower,
    )
  ) {
    vfcLevel2 = "Handling / Riding";
    vfcLevel3 = "Like: performance";
  } else if (
    /\b(engine|motor|hybrid|power|drivetrain|gearbox|transmission|mild hybrid|consumption|efficiency)\b/i.test(
      lower,
    )
  ) {
    vfcLevel2 = "Drivetrain";
    vfcLevel3 = "Like: performance";
  } else if (/\b(brake|braking|bremse)\b/i.test(lower)) {
    vfcLevel2 = "Braking";
    vfcLevel3 = feedbackType === "Defect" ? "Malfunction" : "Like: function";
  } else if (
    /\b(assist|speed limit|parking|lane|kamera|sensor)\b/i.test(lower)
  ) {
    vfcLevel2 = "Driver Assistance Systems";
    vfcLevel3 = feedbackType === "Defect" ? "Malfunction" : "Like: function";
  } else if (
    /\b(interior|cabin|materials|plastic|quality|verarbeitung)\b/i.test(lower)
  ) {
    vfcLevel2 = "Interior design";
    vfcLevel3 = "Look / design appeals";
  } else if (/\b(exterior|styling|front|rear|grille|look)\b/i.test(lower)) {
    vfcLevel2 = "Exterior design";
    vfcLevel3 = "Look / design appeals";
  }

  const summaryPrefix =
    source?.publisher || source?.title
      ? `${source?.publisher || source?.title}: `
      : "";
  const excerpt =
    cleanText.slice(0, 350) + (cleanText.length > 350 ? "…" : "");
  const summary = `[Summary] ${summaryPrefix}${excerpt}`;

  let engineType: SummarizedFeedbackItem["engineType"] = "ICE";
  if (
    /\b(bev|electric|vollelektrisch|i5|i7|battery|laden|charging)\b/i.test(lower)
  ) {
    engineType = "BEV";
  } else if (/\b(phev|plug-in|hybrid)\b/i.test(lower)) {
    engineType = "PHEV";
  }

  return {
    brand: "[BMW]",
    salesDescription: salesDesc,
    country,
    derivate,
    engineType,
    feedbackType,
    summary,
    vfcLevel2Name: vfcLevel2,
    vfcLevel3Name: vfcLevel3,
  };
}

/** Runs work across items with a concurrency cap. Preserved for external utility tests. */
export async function parallelMap<T, R>(
  items: readonly T[],
  concurrency: number,
  fn: (item: T, index: number) => Promise<R>,
  signal: AbortSignal,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {
      if (signal.aborted) throw new Error("Operation cancelled.");
      const current = next++;
      results[current] = await fn(items[current]!, current);
    }
  }
  const workers = Math.max(1, Math.min(concurrency, items.length));
  await Promise.all(Array.from({ length: workers }, worker));
  return results;
}

export interface SummarizeOptions {
  llm?: LlmClient;
  scope?: ProductScope;
  signal?: AbortSignal;
  log?: (message: string) => void;
  concurrency?: number;
}

// --- Row Metadata Compact Packaging ---

const ROW_METADATA_MAX_BYTES = 8 * 1024;

function rowMetadata(metadata: ResearchRecord["metadata"]): {
  metadata: ResearchRecord["metadata"];
  archivedMetadataKeys?: string[];
} {
  const entries: [string, unknown][] = [];
  const archivedMetadataKeys: string[] = [];
  let bytes = 2; // braces
  for (const [key, value] of Object.entries(metadata)) {
    if (key === ASSESSMENT_FIELD || key === "researchAssessments") continue;
    const propertyBytes =
      jsonByteSize({ [key]: value }) - 2 + (entries.length ? 1 : 0);
    if (propertyBytes > ROW_METADATA_MAX_BYTES - bytes) {
      archivedMetadataKeys.push(key);
    } else {
      entries.push([key, value]);
      bytes += propertyBytes;
    }
  }
  return {
    metadata: Object.fromEntries(entries),
    ...(archivedMetadataKeys.length ? { archivedMetadataKeys } : {}),
  };
}

// --- Active Deterministic Summarizer ---

/**
 * Synchronously summarizes research records into BMW feedback rows.
 * Formats already generated, validated relevant assessments from the source agent.
 * Assessed records:
 *   - Only relevant assessments matching original contentHash are included.
 *   - Rejected, unreviewed, or uncertain records are omitted.
 *   - Summaries must be nonempty and positively cite evidence (excerpts or table rows).
 *   - Exact identical summary text + evidence across agents is deduped.
 *   - Produces ONE Raw-like summary row per collected record (recordType='passage',
 *     metadata.textOrigin='ai_summary', Customer Feedback = AI summary).
 *   - Base flat source-only BMW fields are preserved without fake default inference.
 *   - Verbatim evidence is linked in fields['Original Evidence'] and summaryEvidence.
 * Legacy unassessed datasets:
 *   - Returns researchTableRows(dataset) directly so historical datasets/tests do not pay.
 */
export function summarizeResearchRows(
  dataset: ResearchDataset,
): ResearchTableRow[] {
  // Check whether any record has the assessment field.
  const hasAssessments = dataset.records.some((record) =>
    Object.hasOwn(record.fields ?? {}, ASSESSMENT_FIELD),
  );

  // Keep legacy unassessed datasets returning researchTableRows(dataset)
  if (!hasAssessments) {
    return researchTableRows(dataset);
  }

  const sources = new Map(dataset.sources.map((s) => [s.id, s]));
  const rows: ResearchTableRow[] = [];

  for (const record of dataset.records) {
    // Unreviewed records in an assessed dataset are omitted
    if (!Object.hasOwn(record.fields ?? {}, ASSESSMENT_FIELD)) {
      continue;
    }

    const rawAssessments = record.fields?.[ASSESSMENT_FIELD];
    if (!Array.isArray(rawAssessments) || rawAssessments.length === 0) {
      continue;
    }

    // Filter relevant assessments matching record.contentHash
    const relevantAssessments: SourceAssessmentWithSummaries[] = [];
    for (const item of rawAssessments) {
      const parsed = SourceAssessmentWithSummaries.safeParse(item);
      if (!parsed.success) continue;
      const assessment = parsed.data;
      if (
        assessment.contentHash === record.contentHash &&
        assessment.verdict === "relevant"
      ) {
        relevantAssessments.push(assessment);
      }
    }

    if (relevantAssessments.length === 0) {
      continue;
    }

    // Extract positively cited summaries, deduplicating exact matches across agents
    type ValidSummary = {
      text: string;
      excerpts: SummaryExcerpt[];
      tableRows: number[];
    };
    const validSummaries: ValidSummary[] = [];
    const seenKeys = new Set<string>();

    for (const assessment of relevantAssessments) {
      for (const summary of assessment.summaries) {
        const text = summary.text.trim();
        if (!text) continue;

        // Excerpts must be strictly within bounds of record.text
        const validExcerpts = summary.excerpts.filter(
          (e) => e.start >= 0 && e.end <= record.text.length && e.start < e.end,
        );

        // Native table rows must be valid row indices within record.table
        const validTableRows =
          record.recordType === "table" && record.table
            ? summary.tableRows.filter(
                (idx) => idx >= 0 && idx < record.table!.rows.length,
              )
            : [];

        // Include ONLY positively cited summaries (must link to verbatim evidence)
        const isPositivelyCited =
          validExcerpts.length > 0 || validTableRows.length > 0;
        if (!isPositivelyCited) continue;

        // Dedupe exact same summary text + evidence across agents
        const sortedExcKey = [...validExcerpts]
          .sort((a, b) => a.start - b.start || a.end - b.end)
          .map((e) => `${e.start}-${e.end}`)
          .join(",");
        const sortedTblKey = [...validTableRows].sort((a, b) => a - b).join(",");
        const dedupKey = `${text}::[${sortedExcKey}]::[${sortedTblKey}]`;

        if (seenKeys.has(dedupKey)) continue;
        seenKeys.add(dedupKey);

        validSummaries.push({
          text,
          excerpts: validExcerpts,
          tableRows: validTableRows,
        });
      }
    }

    // If no positively cited summaries remain, omit record
    if (validSummaries.length === 0) {
      continue;
    }

    // Produce ONE Raw-like summary row per collected record by joining unit/agent summaries
    const joinedSummaryText = validSummaries.map((s) => s.text).join("\n\n");

    // Collect and merge verbatim spans
    const allExcerpts = validSummaries.flatMap((s) => s.excerpts);
    const sortedSpans = allExcerpts.sort(
      (a, b) => a.start - b.start || a.end - b.end,
    );
    const mergedExcerpts: SummaryExcerpt[] = [];
    for (const span of sortedSpans) {
      const prev = mergedExcerpts.at(-1);
      if (prev && span.start <= prev.end) {
        prev.end = Math.max(prev.end, span.end);
      } else {
        mergedExcerpts.push({ start: span.start, end: span.end });
      }
    }

    const allTableRows = validSummaries.flatMap((s) => s.tableRows);
    const selectedTableIndices = [...new Set(allTableRows)].sort(
      (a, b) => a - b,
    );

    // Exact verbatim evidence text
    const textEvidence = mergedExcerpts
      .map((e) => record.text.slice(e.start, e.end))
      .filter(Boolean);
    const tableEvidence =
      record.table && selectedTableIndices.length > 0
        ? selectedTableIndices.map((idx) => {
            const rowValues = record.table!.rows[idx]!;
            return record.table!.headers
              .map((h, i) => `${h}: ${rowValues[i] ?? ""}`)
              .join("; ");
          })
        : [];
    const originalEvidence = [...textEvidence, ...tableEvidence].join("\n\n");

    // Locators
    const charLocators =
      mergedExcerpts.length > 0
        ? `chars ${mergedExcerpts.map((e) => `${e.start + 1}–${e.end}`).join(", ")}`
        : undefined;
    const tableLocators =
      selectedTableIndices.length > 0
        ? selectedTableIndices.map((idx) => `table row ${idx + 1}`).join(", ")
        : undefined;
    const locParts = [record.locator, charLocators, tableLocators].filter(
      Boolean,
    );
    const locator = locParts.length > 0 ? locParts.join(", ") : undefined;

    // Preserve exact verbatim evidence accessible in flat fields and top summaryEvidence
    const summaryEvidence: SummaryEvidence = {
      sourceId: record.sourceId,
      collectedRecordId: record.id,
      locator,
      excerpts: mergedExcerpts.map((e) => ({
        start: e.start,
        end: e.end,
        text: record.text.slice(e.start, e.end),
      })),
      ...(record.table && selectedTableIndices.length > 0
        ? {
            tableEvidence: {
              headers: record.table.headers,
              rows: selectedTableIndices.map((idx) => record.table!.rows[idx]!),
              rowIndices: selectedTableIndices,
            },
          }
        : {}),
    };

    // Table data restricted to selected indices only
    const table =
      record.table && selectedTableIndices.length > 0
        ? {
            ...record.table,
            rows: selectedTableIndices.map((idx) => record.table!.rows[idx]!),
          }
        : undefined;

    // Base flat source-only BMW fields from researchTableRows, unknown attributes null
    const source = sources.get(record.sourceId);
    const columns = Object.fromEntries(
      BMW_FEEDBACK_HEADERS.map((key) => [key, null]),
    );
    const origFields =
      record.metadata.originalFields &&
      typeof record.metadata.originalFields === "object"
        ? (record.metadata.originalFields as Record<string, unknown>)
        : {};

    const fields: Record<string, unknown> = {
      ...columns,
    };

    if (record.fields) {
      for (const [k, v] of Object.entries(record.fields)) {
        if (
          k !== ASSESSMENT_FIELD &&
          k !== "researchAssessments" &&
          v !== undefined
        ) {
          fields[k] = v;
        }
      }
    }
    for (const header of BMW_FEEDBACK_HEADERS) {
      if (record.fields?.[header] !== undefined) {
        fields[header] = record.fields[header];
      } else if (origFields[header] !== undefined) {
        fields[header] = origFields[header];
      }
    }

    fields.ID = fields.ID ?? record.id;
    fields.Source =
      fields.Source ??
      source?.publisher ??
      source?.title ??
      record.provider ??
      null;
    fields.Country =
      fields.Country ?? record.marketAttribution?.value ?? null;
    fields["Customer Feedback"] = joinedSummaryText;

    if (fields["Vfc level2 Name"] && fields["Vfc level3 Name"]) {
      fields["Vfc level2 3 Name"] =
        `${fields["Vfc level2 Name"]} : ${fields["Vfc level3 Name"]}`;
    } else {
      fields["Vfc level2 3 Name"] = fields["Vfc level2 3 Name"] ?? null;
    }

    fields["Original Evidence"] = originalEvidence;

    // Compact metadata avoiding huge archive amplification
    const { metadata: compactMeta, archivedMetadataKeys } = rowMetadata(
      record.metadata,
    );
    const rowMetadataObj: Record<string, unknown> = {
      ...compactMeta,
      textOrigin: "ai_summary",
      originalFields: fields,
      summaryEvidence,
    };

    const row: ResearchTableRow = {
      ...record,
      id: record.id,
      collectedRecordId: record.id,
      sourceId: record.sourceId,
      recordType: "passage",
      text: joinedSummaryText,
      locator,
      fields,
      market:
        typeof fields.Country === "string"
          ? fields.Country
          : record.marketAttribution?.value,
      metadata: rowMetadataObj,
      ...(table ? { table } : {}),
      ...(archivedMetadataKeys?.length ? { archivedMetadataKeys } : {}),
      sourceAssessments: relevantAssessments.map(
        ({ agentId, verdict, model }) => ({
          agentId,
          verdict,
          model,
        }),
      ),
      contentHash: createHash("sha256")
        .update(
          JSON.stringify({
            text: joinedSummaryText,
            table,
            metadata: rowMetadataObj,
          }),
        )
        .digest("hex"),
    };
    if (!table) {
      delete (row as Partial<ResearchRecord>).table;
    }
    (row as Record<string, unknown>).summaryEvidence = summaryEvidence;

    rows.push(row);
  }

  assertJsonByteBudget(rows, PERSISTED_JSON_MAX_BYTES);
  return rows;
}

/**
 * Async wrapper compatible with existing research block index call sites.
 * Accepts options (scope, llm, signal, log, concurrency) but never calls LLM.
 */
export async function summarizeResearchDataset(
  dataset: ResearchDataset,
  options?: SummarizeOptions,
): Promise<ResearchTableRow[]> {
  if (options?.signal?.aborted) {
    throw new Error("Operation cancelled.");
  }
  return summarizeResearchRows(dataset);
}

