describe("Research Summarizer (Active Deterministic Quality Assessed)", () => {
  it("keeps legacy unassessed datasets returning researchTableRows without modifications", async () => {
    const item1 = createSamplePassageItem("doc_1", "Legacy unassessed text passage.");
    const { source, record } = normalizeItem(item1, "editorial_reviews", "run_test", at);

    const dataset = ResearchDataset.parse({
      schemaVersion: 1,
      runId: "run_test",
      retrievedAt: at,
      sources: [source],
      records: [record],
      results: [],
      synthetic: true,
    });

    const expected = researchTableRows(dataset);
    const syncRows = summarizeResearchRows(dataset);
    expect(syncRows).toEqual(expected);

    const mockLlm: LlmClient = {
      generateObject: vi.fn(),
      generateText: vi.fn(),
    };
    const asyncRows = await summarizeResearchDataset(dataset, {
      llm: mockLlm,
      scope,
      signal: new AbortController().signal,
    });
    expect(asyncRows).toEqual(expected);
    expect(mockLlm.generateObject).not.toHaveBeenCalled();
    expect(mockLlm.generateText).not.toHaveBeenCalled();
  });

  it("omits rejected, unreviewed, or uncertain records in an assessed dataset", () => {
    const text1 = "Relevant text: The steering precision is outstanding.";
    const text2 = "Irrelevant text: Cookie banner and navigation menu.";
    const text3 = "Uncertain text: Possible mention of next generation model.";
    const text4 = "Unreviewed text: Not reviewed by any agent.";

    const item1 = createSamplePassageItem("rec_1", text1);
    const item2 = createSamplePassageItem("rec_2", text2);
    const item3 = createSamplePassageItem("rec_3", text3);
    const item4 = createSamplePassageItem("rec_4", text4);

    const { source: s1, record: r1 } = normalizeItem(item1, "editorial_reviews", "run_test", at);
    const { source: s2, record: r2 } = normalizeItem(item2, "editorial_reviews", "run_test", at);
    const { source: s3, record: r3 } = normalizeItem(item3, "editorial_reviews", "run_test", at);
    const { source: s4, record: r4 } = normalizeItem(item4, "editorial_reviews", "run_test", at);

    // rec_1: relevant with positively cited summary
    const assessment1: SourceAssessmentWithSummaries = {
      version: 1,
      agentId: "editorial_reviews",
      contentHash: r1.contentHash,
      verdict: "relevant",
      reasons: ["Strong feedback on steering."],
      uncertainties: [],
      excerpts: [{ start: 15, end: text1.length }],
      tableRows: [],
      model: "test-model",
      summaries: [
        {
          text: "Steering dynamics are praised for precision.",
          excerpts: [{ start: 15, end: text1.length }],
          tableRows: [],
        },
      ],
    };
    r1.fields = { ...r1.fields, [ASSESSMENT_FIELD]: [assessment1] };

    // rec_2: irrelevant verdict
    const assessment2: SourceAssessmentWithSummaries = {
      version: 1,
      agentId: "editorial_reviews",
      contentHash: r2.contentHash,
      verdict: "irrelevant",
      reasons: ["Boilerplate navigation."],
      uncertainties: [],
      excerpts: [],
      tableRows: [],
      model: "test-model",
      summaries: [
        {
          text: "Cookie policy details.",
          excerpts: [{ start: 0, end: 10 }],
          tableRows: [],
        },
      ],
    };
    r2.fields = { ...r2.fields, [ASSESSMENT_FIELD]: [assessment2] };

    // rec_3: uncertain verdict
    const assessment3: SourceAssessmentWithSummaries = {
      version: 1,
      agentId: "editorial_reviews",
      contentHash: r3.contentHash,
      verdict: "uncertain",
      reasons: ["Speculative forum rumor."],
      uncertainties: ["No verified source."],
      excerpts: [],
      tableRows: [],
      model: "test-model",
      summaries: [
        {
          text: "Unverified rumor.",
          excerpts: [{ start: 0, end: 10 }],
          tableRows: [],
        },
      ],
    };
    r3.fields = { ...r3.fields, [ASSESSMENT_FIELD]: [assessment3] };

    // rec_4: unreviewed (no assessment field)

    const dataset = ResearchDataset.parse({
      schemaVersion: 1,
      runId: "run_test",
      retrievedAt: at,
      sources: [s1, s2, s3, s4],
      records: [r1, r2, r3, r4],
      results: [],
