    expect(rows[0]!.text).toBe("Steering dynamics are praised for precision.");
  });

  it("omits records with source contentHash mismatch", () => {
    const text = "Verified suspension dynamics on gravel roads.";
    const item = createSamplePassageItem("rec_mismatch", text);
    const { source, record } = normalizeItem(item, "editorial_reviews", "run_test", at);

    const assessment: SourceAssessmentWithSummaries = {
      version: 1,
      agentId: "editorial_reviews",
